insert into areas (id, name, description, sort_order) values
  ('great-lawn', 'Great Lawn', 'The big open lawn by the main entrance. The busiest part of the park, and the only area with pre-approved spots for new benches along its edge.', 1),
  ('willow-lake', 'Willow Lake', 'Benches along the lakeshore loop and by the boathouse.', 2),
  ('athletic-fields', 'Athletic Fields', 'Ballfields and the running track on the east side.', 3),
  ('playground', 'Meadow Playground', 'Playground, splash pad and the picnic lawn next to it.', 4),
  ('community-garden', 'Community Garden', 'Plots, the greenhouse and the pollinator meadow.', 5),
  ('picnic-groves', 'Picnic Groves', 'Shaded picnic groves and grills along the east path.', 6),
  ('north-woods', 'North Woods', 'Quiet trail benches under the trees in the north-west.', 7),
  ('old-oak-grove', 'Old Oak Grove', 'The oldest trees in the park, around the memorial circle.', 8),
  ('hilltop-overlook', 'Hilltop Overlook', 'Benches on the ridge path with the view over the lake.', 9);
